using System;

class Program
{
    static bool IsValidTriangle(int a, int b, int c)
    {
        return (a + b > c) && (a + c > b) && (b + c > a);
    }

    static void Main()
    {
        Console.WriteLine($"Sides 3, 4, 5 form valid triangle: {IsValidTriangle(3, 4, 5)}");
